// evals/eval.spec.ts - 2026-10-30 (plan harness-capability-curve-uplift, WS-2; WS-5 R2/R4/R7)
//
// The eval runner. Reads evals/cases/{regression,frontier}/*.json, scores each case, writes a
// result row to evals/results/<id>.jsonl and a summary to evals/results/_summary.json.
//   - replay (default): the stored output is re-scored through the deterministic artifact
//     chain; regression cases must pass; frontier cases are reported.
//   - live (EVAL_MODE=live): the prompt is generated by the real chat pipeline through the proxy
//     for each model in EVAL_MODELS (comma list), then scored the same way plus trajectory.
//   - EVAL_PROMOTE=1: a frontier case with three consecutive passes is moved to regression.
//   - EVAL_SKILL_OVERRIDES={"<skill-id>": "<text>"} (R4): the candidate skill text is installed as the
//     RunState instruction override before every live generation, so a SkillOpt pool candidate is
//     EXECUTED and scored by the registry, not judged as text.
//   - EVAL_CONSTRAINT="<rule>" (R7, E4): live mode runs every case twice, incumbent then candidate
//     (the rule injected as the `learned-constraint` override), compares with compareCandidate and
//     stamps the verdict on the constraint's lifecycle row through the proxy.
//   - EVAL_SETS=regression,frontier  EVAL_KINDS=slides,personas  filter the cases.
//   - EVAL_RESCORE_HOURS=24 (R2): instead of the case files, every AIR record modified in the window
//     under EVAL_HIC_WORKSPACE is re-scored (its shipped slides through the chain); rows go to the
//     event sink (POST /api/telemetry/events) and each failure is filed as a frontier case.
import { describe, it, expect } from 'vitest';
import fs from 'node:fs';
import path from 'node:path';
import { runArtifactChain } from '../services/artifactChain';
import { scoreReplay, buildResult, caseStatus, validateCase, trajectoryFromRun, compareCandidate, type EvalCase, type EvalResult } from '../services/evalSuite';
import { loadJudgeRegistry } from '../services/judgeRegistry';
import { getRun, beginRun, _resetRunStateForTests, setInstructionOverride } from '../services/runState';

const EVALS = path.resolve(__dirname);
const MODE = (process.env.EVAL_MODE || 'replay') as 'replay' | 'live';
const MODELS = (process.env.EVAL_MODELS || 'replay').split(',').map(s => s.trim()).filter(Boolean);
const PROMOTE = process.env.EVAL_PROMOTE === '1';
const OVERRIDES: Record<string, string> = (() => { try { return JSON.parse(process.env.EVAL_SKILL_OVERRIDES || '{}'); } catch { return {}; } })();
const CONSTRAINT = String(process.env.EVAL_CONSTRAINT || '').trim();
const SETS = (process.env.EVAL_SETS || 'regression,frontier').split(',').map(s => s.trim()).filter(Boolean) as Array<'regression' | 'frontier'>;
const KINDS = (process.env.EVAL_KINDS || '').split(',').map(s => s.trim()).filter(Boolean);
const RESCORE_HOURS = Number(process.env.EVAL_RESCORE_HOURS || 0);
const HIC_WORKSPACE = process.env.EVAL_HIC_WORKSPACE || path.resolve(EVALS, '..', 'hic-workspace');
const PROXY = process.env.EVAL_PROXY_BASE || 'http://127.0.0.1:5012';

function readCases(set: 'regression' | 'frontier'): EvalCase[] {
    const dir = path.join(EVALS, 'cases', set);
    if (!fs.existsSync(dir)) return [];
    return fs.readdirSync(dir).filter(f => f.endsWith('.json')).map(f => {
        const c = JSON.parse(fs.readFileSync(path.join(dir, f), 'utf-8')) as EvalCase;
        c.set = set;
        return c;
    }).filter(c => !KINDS.length || KINDS.includes(String(c.kind)));
}

function appendResult(r: EvalResult): void {
    const dir = path.join(EVALS, 'results');
    fs.mkdirSync(dir, { recursive: true });
    fs.appendFileSync(path.join(dir, `${r.case_id}.jsonl`), JSON.stringify(r) + '\n', 'utf-8');
}

function readResults(caseId: string): EvalResult[] {
    const p = path.join(EVALS, 'results', `${caseId}.jsonl`);
    if (!fs.existsSync(p)) return [];
    return fs.readFileSync(p, 'utf-8').split('\n').filter(Boolean).map(l => { try { return JSON.parse(l); } catch { return null; } }).filter(Boolean) as EvalResult[];
}

function installOverrides(extra: Record<string, string> = {}): void {
    for (const [id, text] of Object.entries({ ...OVERRIDES, ...extra })) if (text) setInstructionOverride(id, text);
}

async function generateLive(c: EvalCase, model: string): Promise<any[]> {
    // The real pipeline: sendChatMessage with a minimal context built from the case. Needs the proxy.
    const { sendChatMessage } = await import('../services/corpusChatService');
    const reply = await sendChatMessage(model as any, c.input.prompt, [], {
        corpusText: '',
        researchGoal: c.input.objective,
        uploadedFileContents: c.fixture?.uploadedFileContents,
    } as any);
    const slides = (reply as any)?.slides || (reply as any)?.deck?.slides || [];
    return Array.isArray(slides) ? slides : [];
}

async function scoreCase(c: EvalCase, slides: any[], model: string, candidate?: string): Promise<EvalResult> {
    const pages = c.fixture?.pages || {};
    const scored = await scoreReplay({
        slides,
        chainCtx: {
            artifactType: c.kind,
            researchGoal: c.input.objective,
            engagementSlug: c.input.engagement,
            groundingChunks: c.fixture?.groundingChunks,
            fetchPage: async (p: string) => (pages[p] ?? null),
        } as any,
        runChain: runArtifactChain,
    });
    const trajectory = MODE === 'live' ? trajectoryFromRun(getRun()) : undefined;
    return buildResult(c, { model, mode: MODE, scores: scored.scores, registryPass: scored.pass, trajectory, candidate } as any);
}

async function postJson(url: string, body: unknown): Promise<boolean> {
    try { const r = await fetch(url, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) }); return r.ok; } catch { return false; }
}

const summary: Record<string, unknown>[] = [];

// ------------------------------------------------------------------------------------------------- rescore lane
if (RESCORE_HOURS > 0) {
    function airRecords(): Array<{ path: string; air: any }> {
        const out: Array<{ path: string; air: any }> = [];
        const base = path.join(HIC_WORKSPACE, 'sessions');
        if (!fs.existsSync(base)) return out;
        const cutoff = Date.now() - RESCORE_HOURS * 3600_000;
        const walk = (dir: string) => {
            for (const ent of fs.readdirSync(dir, { withFileTypes: true })) {
                const p = path.join(dir, ent.name);
                if (ent.isDirectory()) { walk(p); continue; }
                if (!ent.name.endsWith('.air.json') || path.basename(dir) !== 'artifacts') continue;
                try { if (fs.statSync(p).mtimeMs < cutoff) continue; out.push({ path: p, air: JSON.parse(fs.readFileSync(p, 'utf-8')) }); } catch { /* skip */ }
            }
        };
        walk(base);
        return out;
    }
    const records = airRecords();
    describe(`rescore lane (${records.length} AIR record(s) in the last ${RESCORE_HOURS} h)`, () => {
        const events: any[] = [];
        for (const { path: fp, air } of records) {
            const aid = String(air.artifactId || path.basename(fp).replace(/\.air\.json$/, ''));
            it(`rescore ${aid}`, async () => {
                const slides = (air.postChain?.shippedPayload && Array.isArray(air.postChain.shippedPayload)) ? air.postChain.shippedPayload
                    : (Array.isArray(air.artifactPayload?.slides) ? air.artifactPayload.slides : null);
                const kind = String(air.artifactType || air.kind || 'slides').replace(/^#/, '');
                if (!slides || !slides.length) { events.push({ kind: 'rescore', run_id: air.runId, artifact_id: aid, pass: null, stage: kind, note: 'no slides to re-score' }); return; }
                _resetRunStateForTests();
                beginRun({ kind: 'artifact', objective: String(air.objective?.userObjective || ''), engagement: path.basename(path.dirname(path.dirname(fp))) });
                const scored = await scoreReplay({ slides, chainCtx: { artifactType: kind, researchGoal: String(air.objective?.userObjective || ''), fetchPage: async () => null } as any, runChain: runArtifactChain });
                const mean = Object.values(scored.scores).length ? Object.values(scored.scores).reduce((a, b) => a + b, 0) / Object.values(scored.scores).length : null;
                events.push({ kind: 'rescore', run_id: air.runId, artifact_id: aid, pass: scored.pass, score: mean, stage: kind, judge_scores: scored.scores, lane: 'host', window_hours: RESCORE_HOURS });
                summary.push({ artifact: aid, kind, pass: scored.pass, scores: scored.scores, below: scored.below.map(b => b.stage) });
                if (!scored.pass) {
                    await postJson(`${PROXY}/api/eval/cases`, {
                        id: `${kind}-rescore-${aid}`.toLowerCase().replace(/[^a-z0-9_-]/g, '-').slice(0, 80), set: 'frontier', kind,
                        input: { objective: String(air.objective?.userObjective || '(objective not recorded in AIR)'), prompt: String(air.prompt || `#${kind}`) },
                        fixture: { output: slides, source_ref: path.relative(HIC_WORKSPACE, fp) },
                        expected: { trajectory: { no_fail_open: true } },
                        origin: { type: 'failed_air', ref: aid, added: new Date().toISOString().slice(0, 10), note: `rescore lane: below ${scored.below.map(b => `${b.stage}=${b.score.toFixed(2)}`).join(', ')}` },
                    });
                }
            });
        }
        it('posts the rows to the event sink and writes the summary', async () => {
            const ok = events.length ? await postJson(`${PROXY}/api/telemetry/events`, { events }) : true;
            const dir = path.join(EVALS, 'results');
            fs.mkdirSync(dir, { recursive: true });
            fs.writeFileSync(path.join(dir, `_rescore-host-${new Date().toISOString().slice(0, 10)}.json`), JSON.stringify({ ran_at: new Date().toISOString(), window_hours: RESCORE_HOURS, posted: ok, artifacts: summary }, null, 2));
            expect(true).toBe(true);
        });
    });
} else {
    // ------------------------------------------------------------------------------------------------- case lanes
    const regression = SETS.includes('regression') ? readCases('regression') : [];
    const frontier = SETS.includes('frontier') ? readCases('frontier') : [];

    describe(`eval suite (${MODE}; ${regression.length} regression, ${frontier.length} frontier${Object.keys(OVERRIDES).length ? `; overrides: ${Object.keys(OVERRIDES).join(',')}` : ''}${CONSTRAINT ? '; constraint E4' : ''})`, () => {
        it('every case file is well-formed', () => {
            const problems = [...regression, ...frontier].flatMap(c => validateCase(c).map(p => `${c.id}: ${p}`));
            expect(problems).toEqual([]);
        });

        it('loads the judge registry (embedded defaults when the proxy is down)', async () => {
            const judges = await loadJudgeRegistry();
            expect(judges.length).toBeGreaterThan(10);
        });

        const incumbentResults: EvalResult[] = [];
        const candidateResults: EvalResult[] = [];

        for (const c of [...regression, ...frontier]) {
            const needsModel = MODE === 'live';
            it(`${c.set}/${c.id}`, async () => {
                for (const model of (needsModel ? MODELS : ['replay'])) {
                    const variants: Array<{ label?: string; extra: Record<string, string> }> = CONSTRAINT && needsModel
                        ? [{ extra: {} }, { label: 'constraint', extra: { 'learned-constraint': CONSTRAINT } }]
                        : [{ extra: {}, label: Object.keys(OVERRIDES).length ? 'skill-override' : undefined }];
                    for (const v of variants) {
                        _resetRunStateForTests();
                        beginRun({ kind: 'artifact', objective: c.input.objective, engagement: c.input.engagement });
                        if (needsModel) installOverrides(v.extra);
                        let slides: any[] | null = c.fixture?.output || null;
                        if (needsModel) slides = await generateLive(c, model);
                        if (!slides || !slides.length) {
                            const r = buildResult(c, { model, mode: MODE, scores: {}, registryPass: false, candidate: v.label } as any);
                            r.failures.push(needsModel ? 'live generation returned no slides' : 'case has no fixture.output to replay');
                            appendResult(r);
                            summary.push({ case: c.id, set: c.set, model, variant: v.label || 'incumbent', pass: false, failures: r.failures });
                            if (c.set === 'regression' && !v.label) expect.fail(r.failures.join('; '));
                            continue;
                        }
                        const r = await scoreCase(c, slides, model, v.label);
                        appendResult(r);
                        (v.label === 'constraint' ? candidateResults : incumbentResults).push(r);
                        const status = caseStatus(c.id, readResults(c.id), c.set);
                        summary.push({ case: c.id, set: c.set, model, variant: v.label || 'incumbent', pass: r.pass, scores: r.scores, failures: r.failures, status });
                        if (PROMOTE && status.promote_to_regression && !v.label) {
                            const from = path.join(EVALS, 'cases', 'frontier', `${c.id}.json`);
                            const to = path.join(EVALS, 'cases', 'regression', `${c.id}.json`);
                            if (fs.existsSync(from)) { const body = JSON.parse(fs.readFileSync(from, 'utf-8')); body.set = 'regression'; fs.writeFileSync(to, JSON.stringify(body, null, 2)); fs.unlinkSync(from); }
                        }
                        if (c.set === 'regression' && !v.label) expect(r.failures, `${c.id} on ${model}`).toEqual([]);
                    }
                }
            });
        }

        if (CONSTRAINT && MODE === 'live') {
            it('E4: the constraint beats the incumbent on the same cases, or stays a candidate', async () => {
                const decision = compareCandidate(incumbentResults, candidateResults);
                const dir = path.join(EVALS, 'results');
                fs.mkdirSync(dir, { recursive: true });
                fs.writeFileSync(path.join(dir, `_constraint-${Date.now().toString(36)}.json`), JSON.stringify({ constraint: CONSTRAINT, decision, ran_at: new Date().toISOString() }, null, 2));
                // stamp the lifecycle row through the engine (reads/writes synthesis/constraint-records.json via the proxy)
                try {
                    const { recordHeldoutVerdict } = await import('../services/promptImprovementEngine');
                    await recordHeldoutVerdict(CONSTRAINT, {
                        before: decision.mean_score_before, after: decision.mean_score_after, cases: incumbentResults.length,
                        decision: decision.decision === 'apply' ? 'accept' : 'reject', reason: decision.reason,
                        scope: KINDS.length === 1 ? { kind: KINDS[0] } : undefined,
                    });
                } catch (e: any) { console.warn('[eval] constraint verdict not stamped:', e?.message || e); }
                summary.push({ constraint: CONSTRAINT, decision });
                expect(decision).toBeTruthy();
            });
        }

        it('writes the summary', () => {
            const dir = path.join(EVALS, 'results');
            fs.mkdirSync(dir, { recursive: true });
            fs.writeFileSync(path.join(dir, '_summary.json'), JSON.stringify({ ran_at: new Date().toISOString(), mode: MODE, models: MODELS, overrides: Object.keys(OVERRIDES), constraint: CONSTRAINT || null, cases: summary }, null, 2));
            expect(true).toBe(true);
        });
    });
}
